function croppyInjectIPhoneTopCompact(raw) {
  // Scriptable's native Close / Share bar is outside HTML and cannot be styled here.
  // In fullscreen WebView, remove only the duplicated HTML safe-area top inset.
  var css = '<style id="croppy-iphone-top-compact">body{padding-top:10px!important}</style>';
  var s = String(raw || "");
  if (s.indexOf('id="croppy-iphone-top-compact"') >= 0) return s;
  return s.indexOf("</head>") >= 0 ? s.replace("</head>", css + "</head>") : s;
}

function croppyInjectIPhoneBootState(raw) {
  var s = String(raw || "");
  var draftCode = safeJSON(bootDraft);
  var historyCode = safeJSON(bootHistory);
  s = s.replace("window.__SOULZ_BOOT_DRAFT = null;", "window.__SOULZ_BOOT_DRAFT = " + draftCode + ";");
  s = s.replace("window.__SOULZ_BOOT_HISTORY = null;", "window.__SOULZ_BOOT_HISTORY = " + historyCode + ";");
  s = s.replace("window.__SOULZ_BOOT_HISTORY = [];", "window.__SOULZ_BOOT_HISTORY = " + historyCode + ";");
  s = s.replace("window.__SOULZ_HOME_MODE = false;", "window.__SOULZ_HOME_MODE = " + (homeMode ? "true" : "false") + ";");
  if (s.indexOf("window.__SOULZ_NATIVE_RECOVERED = false;") >= 0) {
    s = s.replace("window.__SOULZ_NATIVE_RECOVERED = false;", "window.__SOULZ_NATIVE_RECOVERED = " + (croppyNativeRecovered.length ? "true" : "false") + ";");
  } else {
    var homeLine = "window.__SOULZ_HOME_MODE = " + (homeMode ? "true" : "false") + ";";
    s = s.replace(homeLine, homeLine + "\nwindow.__SOULZ_NATIVE_RECOVERED = " + (croppyNativeRecovered.length ? "true" : "false") + ";");
  }
  return s;
}

function croppyInjectIPhoneNativeBridges(raw) {
  var s = String(raw || "");
  var webNoop = "window.__soulzNativeSave = function(){};";
  var native = "window.__soulzNativeSave=function(kind,data){try{var k=kind==='history'?'history':'draft';window.__croppyNativeSavePayload=window.__croppyNativeSavePayload||{};window.__croppyNativeSavePayload[k]=JSON.stringify(data);window.location.href='soulz-save://'+k+'?x='+Date.now()}catch(e){}};" +
    "window.__soulzNativeBackup=function(){try{window.location.href='soulz-backup://export?x='+Date.now()}catch(e){}};";
  if (s.indexOf(webNoop) >= 0) s = s.replace(webNoop, native);
  return s;
}

function croppyInjectIPhoneUpdateStatus(raw) {
  var s = String(raw || "");
  var v = croppyUpdateVersion ? ("v" + croppyUpdateVersion.join(".")) : "";
  var source = croppyUpdateSource || "内蔵";
  var text = source === "最新" ? ("自動更新・最新 " + v) :
    source === "キャッシュ" ? ("オフライン・キャッシュ " + v) :
    ("内蔵版 " + v);
  var tone = source === "最新" ? "latest" : source === "キャッシュ" ? "cached" : "bundled";
  var badge = '<div data-croppy-update-badge="1" class="croppy-iphone-update-status ' + tone + '" aria-label="iPhone版 ' + text + '">' + text + '</div>';
  var css = '<style id="croppy-iphone-update-status-style">' +
    '.croppy-iphone-update-status{display:inline-flex;align-items:center;width:max-content;max-width:100%;margin-top:3px;padding:2px 6px;border-radius:999px;font-size:.54rem;font-weight:850;line-height:1.25;letter-spacing:.01em;border:1px solid rgba(148,163,184,.28);color:#94a3b8;background:rgba(15,23,42,.38)}' +
    '.croppy-iphone-update-status.latest{color:#bbf7d0;border-color:rgba(34,197,94,.38);background:rgba(20,83,45,.28)}' +
    '.croppy-iphone-update-status.cached{color:#fde68a;border-color:rgba(245,158,11,.38);background:rgba(120,53,15,.24)}' +
    'body[data-croppy-theme]:not([data-croppy-theme="dark"]) .croppy-iphone-update-status{color:#64748b;background:#f8fafc;border-color:#cbd5e1}' +
    'body[data-croppy-theme]:not([data-croppy-theme="dark"]) .croppy-iphone-update-status.latest{color:#166534;background:#ecfdf5;border-color:#86efac}' +
    'body[data-croppy-theme]:not([data-croppy-theme="dark"]) .croppy-iphone-update-status.cached{color:#92400e;background:#fffbeb;border-color:#fcd34d}' +
    '</style>';
  if (s.indexOf('id="croppy-iphone-update-status-style"') < 0 && s.indexOf("</head>") >= 0) {
    s = s.replace("</head>", css + "</head>");
  }
  if (s.indexOf('data-croppy-update-badge="1"') < 0) {
    var subtitleRe = /(<div class="subtitle"[^>]*>[\s\S]*?<\/div>)/;
    if (subtitleRe.test(s)) s = s.replace(subtitleRe, "$1" + badge);
    else {
      var titleRe = /(<div class="title"[^>]*>[\s\S]*?<\/div>)/;
      if (titleRe.test(s)) s = s.replace(titleRe, "$1" + badge);
    }
  }
  return s;
}

async function soulzPresentShare(text) {
  try {
    await ShareSheet.present([text]);
  } catch (e) {
    console.log("SOULZ share fallback: " + e);
    try { Pasteboard.copyString(String(text || "")); } catch (copyError) { console.log("SOULZ copy fallback error: " + copyError); }
    try {
      await web.evaluateJavaScript("if(typeof toast==='function')toast('共有を開けなかったためコピーしました')", false);
    } catch (uiError) {}
  }
}


